// ---- API ----
// 取 (profile, size) 对应的图标描述符指针。
// profile 越界自动钳到 0；size 越界自动钳到 PROF_ICON_SIZE_M (32)。
static inline const lv_img_dsc_t* profile_icon_get(int profile, int size) {
    int p = (profile < 0 || profile >= PROF_ICON_COUNT) ? 0 : profile;
    int s = size;
    if (s != PROF_ICON_SIZE_S && s != PROF_ICON_SIZE_M && s != PROF_ICON_SIZE_L) s = PROF_ICON_SIZE_M;
    static const lv_img_dsc_t* const table[PROF_ICON_COUNT][3] = {
        { &prof_icon_win_S_desc,  &prof_icon_win_M_desc,  &prof_icon_win_L_desc  },
        { &prof_icon_mac_S_desc,  &prof_icon_mac_M_desc,  &prof_icon_mac_L_desc  },
        { &prof_icon_game_S_desc, &prof_icon_game_M_desc, &prof_icon_game_L_desc },
        { &prof_icon_work_S_desc, &prof_icon_work_M_desc, &prof_icon_work_L_desc },
    };
    int si = (s == PROF_ICON_SIZE_S) ? 0 : (s == PROF_ICON_SIZE_L ? 2 : 1);
    return table[p][si];
}
